def resolve(path, cwd, links):
    # Validate cwd is canonical absolute
    if not cwd or cwd[0] != '/':
        return None

    # Handle trailing slash in cwd
    if len(cwd) > 1 and cwd[-1] == '/':
        return None  # cwd should be canonical (no trailing slash except for '/')

    # Start with cwd if path is relative, otherwise start with '/'
    if path and path[0] == '/':
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Parse next component
        if not remaining:
            break

        # Find next '/'
        slash_pos = remaining.find('/')
        if slash_pos == -1:
            component = remaining
            remaining = ''
        else:
            component = remaining[:slash_pos]
            remaining = remaining[slash_pos + 1:]

        # Skip empty components and '.'
        if not component or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None  # Too many links

            target = links[candidate]

            # Resolve target relative to directory containing the link
            if target[0] == '/':
                # Absolute target
                current = '/'
                remaining = target[1:] + ('/' + remaining if remaining else '')
            else:
                # Relative target - relative to directory containing the link
                link_dir = current if current == '/' else current
                if link_dir != '/':
                    link_dir_parent = link_dir.rfind('/')
                    if link_dir_parent == 0:
                        link_dir = '/'
                    else:
                        link_dir = link_dir[:link_dir_parent]

                # Prepare to process target relative to link_dir
                if link_dir == '/':
                    current = '/'
                    remaining = target + ('/' + remaining if remaining else '')
                else:
                    current = link_dir
                    remaining = target + ('/' + remaining if remaining else '')
        else:
            # Normal component, just append
            current = candidate

    # Return result: no trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current if not current.endswith('/') else current[:-1]

